"""Replay two independently devised in-memory review probes; write no files.
Run: python3 -I .session/artifacts/counterexamples.py
Repository root is derived from this session artifact, not from the cwd.
"""
import contextlib
import copy
import hashlib
import io
import json
from pathlib import Path
import sys

sys.dont_write_bytecode = True
root = Path(__file__).resolve().parents[2]
writing = root / "benchmark/writing"
source = (writing / "verify_method.py").read_bytes()
method_bytes = (writing / "method.json").read_bytes()
controls_bytes = (writing / "controls.json").read_bytes()
controls = json.loads(controls_bytes)

class MemoryFile:
    def __init__(self, contents):
        self.contents = contents
    def read_bytes(self):
        return self.contents

class MemoryRoot:
    def __init__(self, modified_controls):
        self.files = {
            "method.json": method_bytes,
            "controls.json": json.dumps(modified_controls).encode(),
        }
    def __truediv__(self, name):
        return MemoryFile(self.files[name])

def trial(name, modified_controls, changes, expected):
    namespace = {"__file__": str(writing / "verify_method.py"), "__name__": "review_probe"}
    exec(compile(source, namespace["__file__"], "exec"), namespace)
    namespace["HERE"] = MemoryRoot(modified_controls)
    previous = sys.argv
    try:
        sys.argv = [namespace["__file__"]]
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            namespace["main"]()
        result = json.loads(output.getvalue())
        actual = {k: result[k] for k in (
            "status", "rejected_count", "positive_controls", "native_executions",
            "agent_runs", "benchmark_ready", "meaning"
        )}
    except Exception as error:
        actual = {"exception": type(error).__name__, "reason": str(error)}
    finally:
        sys.argv = previous
    return {"id": name, "changes_from_pinned_controls": changes,
            "expected": expected, "actual": actual}

version_controls = copy.deepcopy(controls)
version_controls["examples"][1]["original"]["result.synth"]["version"] = "SYNTHETIC-v0"
version_controls["examples"][1]["candidate"]["original_after"]["result.synth"]["version"] = "SYNTHETIC-v0"
version_changes = [
    {"path": "/examples/1/original/result.synth/version", "value": "SYNTHETIC-v0"},
    {"path": "/examples/1/candidate/original_after/result.synth/version", "value": "SYNTHETIC-v0"},
]
key_controls = copy.deepcopy(controls)
del key_controls["pair"]["frozen"]["key_revision"]
for arm in key_controls["pair"]["arms"]:
    del arm["settings"]["key_revision"]
key_changes = [
    {"path": "/pair/frozen/key_revision", "delete": True},
    {"path": "/pair/arms/0/settings/key_revision", "delete": True},
    {"path": "/pair/arms/1/settings/key_revision", "delete": True},
]
results = {
    "checker_sha256": hashlib.sha256(source).hexdigest(),
    "method_sha256": hashlib.sha256(method_bytes).hexdigest(),
    "original_controls_sha256": hashlib.sha256(controls_bytes).hexdigest(),
    "counterexamples": [
        trial("original-to-output-version-drift", version_controls, version_changes,
              "Reject synthetic modification as version-drift: original v0 is preserved outside the workspace but output is v1. W4 requires output save version to match its original, not just the fixture-wide frozen version."),
        trial("missing-paired-key-binding", key_controls, key_changes,
              "Reject absent frozen key revision even though both arms omit it identically. E6 and comparison.matched_fields require a pinned case/key revision; symmetric omission is not comparability."),
    ],
    "limits": "Only fictional contract checks. Each probe changes controls in memory and invokes the unmodified checker main, including all 35 authored negatives; no checker, method or repository bytes are edited. These are completeness gaps in synthetic verification, not evidence of native false success, broken LabVIEW artifacts or benchmark readiness. A fixture hash comparison would detect changed input bytes; the point is that checker consistency alone does not enforce these obligations.",
}
assert (writing / "verify_method.py").read_bytes() == source
assert (writing / "method.json").read_bytes() == method_bytes
assert (writing / "controls.json").read_bytes() == controls_bytes
print(json.dumps(results, indent=2, sort_keys=True))

